<?php
include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';
$school=(int)($_SESSION['login_school_id']??0);$id=(int)($_GET['id']??0);
$s=$conn->prepare("SELECT a.*,s.id_no,s.name student_name,s.nivel,s.grado,s.seccion,uc.name created_name,uu.name updated_name FROM asistencia a INNER JOIN student s ON s.id=a.student_id LEFT JOIN users uc ON uc.id=a.created_by LEFT JOIN users uu ON uu.id=a.updated_by WHERE a.id=? AND a.school_id=? LIMIT 1");$s->bind_param('ii',$id,$school);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if(!$r){echo '<div class="alert alert-warning">Registro no encontrado.</div>';exit;}
$audit=[];$q=$conn->query("SELECT al.action,al.details,al.created_at,u.name user_name FROM attendance_audit_log al LEFT JOIN users u ON u.id=al.user_id WHERE al.school_id=$school AND al.attendance_id=$id ORDER BY al.id DESC LIMIT 50");while($q&&($x=$q->fetch_assoc()))$audit[]=$x;
function arh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<div class="container-fluid px-1"><div class="row"><div class="col-md-7"><h6 class="font-weight-bold text-primary mb-3">Marcación</h6><table class="table table-sm table-bordered"><tr><th>Estudiante</th><td><?php echo arh($r['student_name'].' · '.$r['id_no']);?></td></tr><tr><th>Aula</th><td><?php echo arh($r['nivel'].' · '.$r['grado'].' '.$r['seccion']);?></td></tr><tr><th>Fecha y hora</th><td><?php echo date('d/m/Y',strtotime($r['fecha'])).' · '.substr($r['hora'],0,5);?></td></tr><tr><th>Tipo / estado</th><td><?php echo arh($r['tipo'].' · '.(in_array($r['estado'],['Normal','Temprano'])?'Presente':$r['estado']));?></td></tr><tr><th>Origen</th><td><?php echo arh($r['source']?:'Manual');?></td></tr><tr><th>Notas</th><td><?php echo arh($r['notes']?:'Sin notas');?></td></tr><tr><th>Justificación</th><td><?php echo arh(($r['justification_status']?:'No aplica').($r['justification_reason']?' · '.$r['justification_reason']:''));?></td></tr><tr><th>Registrado / actualizado por</th><td><?php echo arh(($r['created_name']?:'Sistema').' / '.($r['updated_name']?:'Sin cambios'));?></td></tr></table></div><div class="col-md-5"><h6 class="font-weight-bold text-primary mb-3">Historial</h6><div style="max-height:360px;overflow:auto"><?php if(!$audit):?><div class="text-muted small">No hay movimientos adicionales.</div><?php endif;?><?php foreach($audit as $a):?><div class="border-left border-primary pl-3 pb-3"><strong class="d-block small"><?php echo arh(str_replace('_',' ',$a['action']));?></strong><span class="small text-muted"><?php echo date('d/m/Y H:i',strtotime($a['created_at'])).' · '.arh($a['user_name']?:'Sistema');?></span><?php $d=json_decode($a['details'],true);if($d):?><div class="small mt-1"><?php echo arh(implode(' · ',array_filter(array_map(function($k,$v){return is_scalar($v)?$k.': '.$v:null;},array_keys($d),$d))));?></div><?php endif;?></div><?php endforeach;?></div></div></div></div>
